def calculate_discounted_total(subtotal: float, discount: float) -> float:
    """Designed primary: direct multiplicative form."""
    total = subtotal * (1 - discount)
    return round(total, 2)

at_code:
def acceptance_test(result, *args) -> bool:
    """Acceptance test for calculate_discounted_total.
    result: the numeric return value under test.
    args:   (subtotal, discount) — the original inputs.
    Returns True only if result is a valid number matching the spec.
    """
    try:
        subtotal, discount = args
        # Reject non-numeric / None results outright (catches missing-return fault).
        if result is None or not isinstance(result, (int, float)):
            return False
        if isinstance(result, bool):
            return False
        # Result must be within valid bounds: between 0 and the subtotal.
        if result < 0 or result > subtotal + 1e-6:
            return False
        expected = round(subtotal * (1 - discount), 2)
        return abs(result - expected) < 0.01
    except Exception:
        return False
